import { Link } from "react-router-dom";

function Navbar() {
  return (
    <nav style={{ padding: "10px", background: "#222", color: "#fff" }}>
      <h2>🌱 Nursery System</h2>

      <Link to="/" style={{ margin: "10px", color: "white" }}>Home</Link>
      <Link to="/add-child" style={{ margin: "10px", color: "white" }}>Add Child</Link>
      <Link to="/add-report" style={{ margin: "10px", color: "white" }}>Add Report</Link>
      <Link to="/attendance" style={{ margin: "10px", color: "white" }}>Attendance</Link>
      <Link to="/admin" style={{ margin: "10px", color: "white" }}>Admin</Link>
      <Link to="/classes" style={{ margin: "10px", color: "white" }}>Classes</Link>
    </nav>
  );
}

export default Navbar;
